SourceCode.Declaration:
/// <summary>
/// CB223_PalletRounding
/// Similar to PriceDiscCacheKey, provides the logic for creating a cache key that holds
/// values used for searching pallet rounding policies.
/// </summary>
class METPalletRoundingPolicyCacheKey
{
    public InventSiteId                         siteId;
    public METCustomerGroupAll                  accountCode;
    public InventCustVendRel                    accountRel;
    public METItemTableGroup                    itemCode;
    public METPalletRoundingPolicyItemRelation  itemRel;

}

Method.Source:
public static METPalletRoundingPolicyCacheKey construct()
{
    return new METPalletRoundingPolicyCacheKey();
}

/// <summary>
/// Initializes the <c>METPalletRoundingPolicyCacheKey</c>.
/// </summary>
/// <param name = "_siteId">The <c>InventSiteId</c> value.</param>
/// <param name = "_accountCode">The account code.</param>
/// <param name = "_accountRel">The customer or customer operations group id.</param>
/// <param name = "_itemCode">The item code.</param>
/// <param name = "_itemRel">Item number or prodcut categorie.</param>
public void initialize(
    InventSiteId                        _siteId,
    METCustomerGroupAll                 _accountCode,
    InventCustVendRel                   _accountRel,
    METItemTableGroup                   _itemCode,
    METPalletRoundingPolicyItemRelation _itemRel)
{
    this.siteId         = _siteId;
    this.accountCode    = _accountCode;
    this.accountRel     = _accountRel;
    this.itemCode       = _itemCode;
    this.itemRel        = _itemRel;
}

/// <summary>
/// Composes a key based of the passed values and the current data area id.
/// </summary>
/// <returns>A container representing the key</returns>
public container pack()
{
    str key;

    key = curext()                      +
          ' '                           +
          siteId                        +
          ' '                           +
          int2str(accountCode)          +
          ' '                           +
          accountRel                    +
          ' '                           +
          int2str(itemCode)             +
          ' '                           +
          itemRel;

    return [key];
}

/// <summary>
/// Remove a pallet rounding policy header from the cache if the pallet rounding policy record was updated (deactivated)/deleted
/// </summary>
/// <param name = "_palletRoundingPolicyHeader"><c>METPalletRoundingPolicyHeader</c> record</param>
static void removePalletRoundingPolicyCache(METPalletRoundingPolicyHeader _palletRoundingPolicyHeader)
{
    METPalletRoundingPolicyLine policyLine;

    while select policyLine
           where policyLine.InventSiteId == _palletRoundingPolicyHeader.InventSiteId
    {
        METPalletRoundingPolicyCacheKey::flushSelectedPalletRoundingPolicyCache(policyLine);
    }
}

/// <summary>
/// Remove a pallet rounding policy line from the cache if the pallet rounding policy record was updated/deleted
/// </summary>
/// <param name = "_palletRoundingPolicyLine"><c>METPalletRoundingPolicyLine</c> record</param>
static void removePalletRoundingPolicyLineCache(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{
    METPalletRoundingPolicyCacheKey::flushSelectedPalletRoundingPolicyCache(_palletRoundingPolicyLine);
}

/// <summary>
/// Remove a pallet rounding policy key from the cache
/// </summary>
/// <param name = "_palletRoundingPolicyLine"><c>METPalletRoundingPolicyLine</c> record</param>
private static void flushSelectedPalletRoundingPolicyCache(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{
    METPalletRoundingPolicyCacheKey cacheKey = METPalletRoundingPolicyCacheKey::construct();

    if (_palletRoundingPolicyLine.ItemCode == METItemTableGroup::Table)
    {
        cacheKey.initialize(_palletRoundingPolicyLine.InventSiteId, _palletRoundingPolicyLine.AccountCode, _palletRoundingPolicyLine.AccountRelation, _palletRoundingPolicyLine.ItemCode, _palletRoundingPolicyLine.AccountRelation);

        METPalletRoundingPolicyCacheKey::removeFindPalletRoundingGlobalObjectCache(cacheKey);
    }
    else
    {
        // TODO loop through hierarchy with previous category value to delete any keys under the main node
    }
}

/// <summary>
///    Retrieves an object from the <c>SysGlobalObjectCache</c> object.
/// </summary>
/// <param name="_scope">
///    A string type that specifies the scope or the owner of the cached object.
/// </param>
/// <param name="_key">
///    A container type that specifies the key to the cached object.
/// </param>
/// <returns>
///    A container type that specifies the retrieved object.
/// </returns>
public static container getPalletRoundingPolicyCacheValue(str _scope, container _key)
{
    SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();
    return sysGlobalObjectCache.find(_scope, _key);
}

/// <summary>
///    Inserts an object to the <c>SysGlobalObjectCache</c> object.
/// </summary>
/// <param name="_scope">
///    A string type that specifies the scope or the owner of the cached object.
/// </param>
/// <param name="_key">
///    A container type that specifies the key to the cached object.
/// </param>
/// <param name="_value">
///    A container type that has the object to cache.
/// </param>
public static void insertPalletRoundingPolicyCache(str _scope, container _key, container _value)
{
    SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();
    sysGlobalObjectCache.insert(_scope, _key, _value);
}

/// <summary>
/// Remove key from the cache
/// </summary>
/// <param name = "_cacheKey"><c>METPalletRoundingPolicyCacheKey</c> to remove from the cache</param>
private static void removeFindPalletRoundingGlobalObjectCache(METPalletRoundingPolicyCacheKey _cacheKey)
{
    container key = _cacheKey.pack();

    SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();

    if (sysGlobalObjectCache.find(METPalletRoundingPolicySearch::retrieveCacheScope(), key) != conNull())
    {
        sysGlobalObjectCache.remove(METPalletRoundingPolicySearch::retrieveCacheScope(), key);
    }
}
